import re

def parse_nested_parens(paren_string: str) -> List[int]:
    # Split input by any non-parenthesis characters, filter out empty strings
    groups = re.findall(r'\(+\)+|\(+|\)+', paren_string)  # initial guess but not correct for groups
    # Instead, as per clarification, groups are sequences of only parentheses separated by any non-parenthesis chars
    # So better to split by any non-parenthesis char:
    groups = re.split(r'[^()]+', paren_string)
    groups = [g for g in groups if g]  # remove empty strings

    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            else:  # ch == ')'
                current_depth -= 1
        result.append(max_depth)
    return result


