def anti_shuffle(s):
    words = s.split(' ')
    result = []
    for w in words:
        if len(w) <= 1:
            result.append(w)
        else:
            sorted_w = ''.join(sorted(w))
            if w[0].isupper():
                # If original word starts with uppercase, reorder so uppercase letters come first in original order,
                # then the rest sorted ascending.
                # But task example: 'Hello' -> 'Hello' (same), so sorting did not change order.
                # Actually in example 'Hello' remains 'Hello' which is sorted ascending, so just sorting ascending is enough.
                # So we just return sorted_w as is.
                result.append(sorted_w)
            else:
                result.append(sorted_w)
    return ' '.join(result)


