from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    # Split the input string into groups
    groups = paren_string.split()
    # For each group, map '(' to +1 and ')' to -1,
    # then compute cumulative sums and find the max depth
    # No explicit loops or recursion: use map and max with generator expressions
    def max_depth(group: str) -> int:
        # Map '(' to 1, ')' to -1
        increments = map(lambda c: 1 if c == '(' else -1, group)
        # Compute cumulative sums without loops or recursion using itertools.accumulate
        from itertools import accumulate
        depths = accumulate(increments)
        return max(depths)
    return list(map(max_depth, groups))


