def monotonic(l):
    if isinstance(l, list):
        # For list input: return only a boolean.
        # Check duplicates:
        if len(set(l)) != len(l):
            return False
        # Check strictly monotonic increasing or decreasing:
        increasing = all(x < y for x, y in zip(l, l[1:]))
        decreasing = all(x > y for x, y in zip(l, l[1:]))
        return increasing or decreasing
    elif isinstance(l, str):
        # For string input: return (bool, string) if monotonic, else False
        if len(set(l)) != len(l):
            return False
        increasing = all(x < y for x, y in zip(l, l[1:]))
        decreasing = all(x > y for x, y in zip(l, l[1:]))
        if increasing or decreasing:
            return True, l
        else:
            return False


