from collections import Counter

def search(lst):
    if not lst:
        return -1
    # If elements are strings, return the max element lexicographically as string
    if isinstance(lst[0], str):
        return max(lst)
    # Otherwise, lst contains positive integers
    freq = Counter(lst)
    # candidates are integers x where freq[x] >= x
    candidates = [x for x in freq if freq[x] >= x and x > 0]
    return str(max(candidates)) if candidates else "-1"


