def total_match(lst1, lst2):
    # Check if any list contains strings
    def contains_str(lst):
        return any(isinstance(x, str) for x in lst)

    # If both have strings
    if contains_str(lst1) or contains_str(lst2):
        # Gather all strings from both lists
        strs = []
        if contains_str(lst1):
            strs.extend([x for x in lst1 if isinstance(x, str)])
        if contains_str(lst2):
            strs.extend([x for x in lst2 if isinstance(x, str)])
        # Return the longest string as a list
        # If multiple longest strings, return the first one
        if not strs:
            # no strings? (should not happen here)
            return []
        longest = max(strs, key=len)
        return [longest]

    # Now both lists are integer lists (or empty)
    # Calculate total digits for each list
    def total_digits(lst):
        total = 0
        for n in lst:
            # count digits ignoring sign
            total += len(str(abs(n)))
        return total

    td1 = total_digits(lst1)
    td2 = total_digits(lst2)

    # Decide which list to return
    if td1 <= td2:
        chosen = lst1
    else:
        chosen = lst2

    # Return chosen list sorted ascending but maintaining original order
    # This means: sort the elements by value ascending, but preserve original relative order of equal elements
    # Since all unique integers, just sort ascending but stable order is natural
    # But we must "maintain original order" at the same time as "ascending order"
    # This is contradictory: ascending order and maintaining original order are conflicting
    # The task says: "the order of the output list must be in ascending order but at the same time maintain its original order."
    # The only way to interpret this is: sort ascending, but for equal elements maintain original order (stable sort)
    # For integers, stable sort is default in Python's sort, so just sort ascending.
    # Actually, if duplicate elements exist, stable sort preserves their original order.
    # So just do sorted(chosen) is enough.

    # But the examples show, e.g. total_match([12, 345], [123, 45]) ➞ [123, 45]
    # The output list is [123, 45] - which is not sorted ascending (45 < 123)
    # So the example contradicts the "ascending order" requirement in the task.
    # The example is: total_match([12, 345], [123, 45]) ➞ "123 45"
    # They returned the second list, but the order is as in the original list, not sorted ascending.
    # So the example shows that the output list should preserve original order (not sorted ascending).
    # Next example:
    # total_match([12, 345], [12, 12, 345, 789]) ➞ "12 345"
    # They returned the first list (because total digits is less), but the output is [12, 345], same order
    # So actually the example outputs contradict the text "the order of the output list must be in ascending order but at the same time maintain its original order."
    # The examples show that the output list is returned in its original order.
    # So it seems the "ascending order" instruction is contradicted by the examples.
    # The clarifying question says: "Where it conflicts, follow the answer." The answer did not clarify this.
    # So by rule 3, pick the least surprising behaviour: return the chosen list in its original order.
    # Because sorting ascending but maintaining original order is contradictory.
    # So we return the chosen list as-is (original order).

    return list(chosen)


