def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    def is_sorted(a):
        return all(a[i] <= a[i + 1] for i in range(len(a) - 1))

    # Helper to check if arr rotated right k times is sorted
    def check(k):
        # Rotation to right by k: arr[-k:] + arr[:-k]
        rotated = arr[-k:] + arr[:-k]
        return is_sorted(rotated)

    # Since no loops allowed, we use recursion to find minimal k
    def find_shift(k):
        if k == n:
            return False
        if check(k):
            return k
        return find_shift(k + 1)

    return find_shift(0)


