def select_words(s, n):
    if not s:
        return []
    vowels = set("aeiouAEIOU")
    words = s.split()
    def count_consonants(w):
        return sum(1 for c in w if c.isalpha() and c not in vowels)
    filtered = [w for w in words if count_consonants(w) == n]
    sorted_filtered = sorted(filtered)
    sorted_set = set(sorted_filtered)
    result = [w for w in words if w in sorted_set and count_consonants(w) == n]
    return result


