def maximum(arr, k):
    # Helper function: insertion sort ascending
    def insertion_sort(nums):
        for i in range(1, len(nums)):
            key = nums[i]
            j = i - 1
            while j >= 0 and nums[j] > key:
                nums[j + 1] = nums[j]
                j -= 1
            nums[j + 1] = key
        return nums

    if k == 0:
        return []

    # Find the k largest elements (including duplicates)
    # We can do this by selecting the k largest elements manually without sorting the whole array
    # Since the array length max is 1000, we can afford a simple approach:
    # 1. Copy arr
    # 2. Find the k-th largest element by repeatedly finding max k times
    # 3. Collect all elements >= k-th largest element, if more than k, adjust accordingly.
    # But since we must not use built-in sort, let's do a partial selection.

    # Step 1: Find the k largest elements by repeated max extraction
    # We'll do it with a simple selection approach

    # Make a copy to mark used elements
    used = [False] * len(arr)
    result = []

    for _ in range(k):
        current_max = None
        current_idx = -1
        for idx, val in enumerate(arr):
            if not used[idx]:
                if current_max is None or val > current_max:
                    current_max = val
                    current_idx = idx
        used[current_idx] = True
        result.append(current_max)

    # Now result contains the k largest elements in descending order (because we pick max each time)
    # We want them in ascending order, so we insertion sort result ascending
    return insertion_sort(result)


