def digits(n):
    s = str(n)
    odd_digits = [int(d) for d in s if int(d) % 2 == 1]
    even_digits = [int(d) for d in s if int(d) % 2 == 0]

    if not odd_digits:
        return 0
    if not even_digits:
        return 1 if len(odd_digits) == 0 else 1  # but if no even digits, returns product of odds anyway

    product = 1
    for d in odd_digits:
        product *= d
    return product


