    def ceil_num(x):
        i = int(x)
        if x == i:
            return i
        if x > 0:
            return i + 1
        return i  # for negative floats, ceiling is the integer part if no fraction

    total = 0
    for num in lst:
        c = ceil_num(num)
        total += c * c
    return str(total)


