def order_by_points(nums):
    if not nums:
        return []

    def digit_sum(x):
        s = str(x).lstrip('-')
        return sum(int(ch) for ch in s)

    indexed_nums = list(enumerate(nums))
    indexed_nums.sort(key=lambda x: (digit_sum(x[1]), x[0]))
    sorted_nums = [str(x[1]) for x in indexed_nums]
    return ", ".join(sorted_nums)


