def solve(s):
    has_letter = any(c.isalpha() for c in s)
    if has_letter:
        # Toggle case for letters, keep others as is
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)
    else:
        # No letters: reverse the string and return as int
        return int(s[::-1])


