def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Since elements are unique, a rotated sorted array will have at most one "drop"
    # i.e. one place where arr[i] > arr[i+1].
    drops = 0
    for i in range(n):
        if arr[i] > arr[(i+1) % n]:
            drops += 1
            if drops > 1:
                return False
    return True


