import re

def anti_shuffle(t):
    def process_word(word):
        # If word contains any non-alphabetic character, return it unchanged
        if any(not c.isalpha() for c in word):
            return word
        # Otherwise, return sorted characters (ascending by character code)
        return ''.join(sorted(word))

    # Tokenize the string into words and spaces
    tokens = re.findall(r'\S+|\s+', t)
    # Process words and keep spaces as is
    result = []
    for token in tokens:
        if token.isspace():
            result.append(token)
        else:
            result.append(process_word(token))
    return ''.join(result)


