def move_one_ball(seq):
    if not seq:
        return True

    n = len(seq)
    # Since values are distinct, the sorted sequence is unique
    sorted_seq = sorted(seq)

    # Check if seq is a rotation of sorted_seq
    # If yes, return True, else False

    # One way: find the index of the smallest element in seq
    # and rotate seq to start from there, then compare to sorted_seq
    min_val = min(seq)
    min_index = seq.index(min_val)

    rotated = seq[min_index:] + seq[:min_index]
    return rotated == sorted_seq


