def select_words(text, count):
    vowels = set("aeiouAEIOU")
    if not text:
        return []
    result = []
    for word in text.split():
        consonant_count = sum(1 for ch in word if ch.isalpha() and ch not in vowels)
        if consonant_count == count:
            result.append(word)
    return result


