def triples_sum_to_zero(l: list):
    """
    Returns True if there exist three distinct elements by value in the list whose sum is zero,
    and False otherwise.
    """
    s = set(l)
    if len(s) < 3:
        return False
    nums = sorted(s)
    n = len(nums)
    for i in range(n - 2):
        a = nums[i]
        left, right = i + 1, n - 1
        while left < right:
            b, c = nums[left], nums[right]
            total = a + b + c
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1
    return False


