def anti_shuffle(s):
    """
    Write a function that takes a string and returns an ordered version of it.
    The function sorts characters within each word independently by ASCII order,
    treating spaces as separators that remain in their original positions.
    """
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)


