def anti_shuffle(s):
    result = []
    word = []
    for ch in s:
        if ch != ' ':
            word.append(ch)
        else:
            if word:
                sorted_word = ''.join(sorted(word))
                result.append(sorted_word)
                word = []
            result.append(ch)
    if word:
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)
    return ''.join(result)


