def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    # Check if arr is already sorted
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Count the number of places where arr[i] > arr[i+1]
    drops = 0
    drop_index = -1
    for i in range(n-1):
        if arr[i] > arr[i+1]:
            drops += 1
            drop_index = i

    # If more than one drop, cannot be sorted by rotation
    if drops > 1:
        return False

    # If no drops, already sorted
    if drops == 0:
        return True

    # Check if rotation by drop_index+1 makes array sorted
    # Right shift by k means last k elements come to front
    # So rotated array = arr[-k:] + arr[:-k]
    k = n - (drop_index + 1)
    rotated = arr[-k:] + arr[:-k]

    return all(rotated[i] <= rotated[i+1] for i in range(n-1))


