    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # negative number: first digit after '-' is negative, rest positive
            total = -int(s[1])
            for ch in s[2:]:
                total += int(ch)
            return total
        else:
            return sum(int(ch) for ch in s)
    return sorted(nums, key=digit_sum)


