from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    depths = []
    current_depth = 0
    max_depth = 0
    in_group = False

    for ch in paren_string:
        if ch == '(':
            current_depth += 1
            in_group = True
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch == ')':
            current_depth -= 1
            if current_depth < 0:
                # unbalanced closing, reset to zero (ignore)
                current_depth = 0
            # if current_depth == 0, group ended
            if current_depth == 0 and in_group:
                depths.append(max_depth)
                max_depth = 0
                in_group = False
        else:
            # separator encountered inside a group that is not closed yet
            # but parentheses group must be balanced, so ignore separators inside groups
            # or if outside group, do nothing
            pass

    # If string ended but group not closed (unbalanced)
    # We don't append incomplete groups (no closing parentheses)
    # This behavior can be adjusted if needed.

    return depths


