def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Check if already sorted
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Find the number of "breaks" where arr[i] > arr[i+1]
    breaks = 0
    break_index = -1
    for i in range(n-1):
        if arr[i] > arr[i+1]:
            breaks += 1
            break_index = i
            if breaks > 1:
                return False

    # If there is no break, already sorted (handled above)
    # If there is exactly one break, check if rotation at break+1 sorts the array
    # The rotation by right shifts is equivalent to rotating the array so that arr[break_index+1] becomes the first element

    # Check if last element <= first element after rotation
    if arr[-1] > arr[0]:
        return False

    return True


