def solve(s):
    # Define letters as ASCII letters only (a-z, A-Z)
    has_letter = any('a' <= c <= 'z' or 'A' <= c <= 'Z' for c in s)
    if not has_letter:
        # No ASCII letters: reverse entire string as-is
        return s[::-1]
    else:
        # For ASCII letters, flip case; else keep same
        result = []
        for c in s:
            if 'a' <= c <= 'z':
                result.append(c.upper())
            elif 'A' <= c <= 'Z':
                result.append(c.lower())
            else:
                result.append(c)
        return ''.join(result)


