def parse_music(notes: str) -> list[int]:
    legend = {'o': 4, 'o|': 2, '.|': 1}
    result = []
    # Split the input by spaces to get tokens that may contain multiple notes concatenated
    tokens = notes.split()
    for token in tokens:
        i = 0
        while i < len(token):
            # Try to match the longest possible note ('o|' or '.|') first
            if i + 1 < len(token) and token[i:i+2] in legend:
                result.append(legend[token[i:i+2]])
                i += 2
            elif token[i] in legend:
                result.append(legend[token[i]])
                i += 1
            else:
                # Unknown character, skip it
                i += 1
    return result


