def prime_length(s):
    """Write a function that takes a string and returns if the string
    length is a prime number or not.
    """
    n = len(s)
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True


