def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        if n >= 0:
            return sum(int(d) for d in s)
        else:
            # negate first digit before summing
            first_digit = -int(s[0])
            return first_digit + sum(int(d) for d in s[1:])
    return sorted(nums, key=digit_sum)


