import re

def parse_music(music: str):
    """
    Parse a music string into a list of note durations.

    Notes are represented as letters A-G, optionally followed by '#' or 'b',
    and optionally followed by an octave number (default 4 if missing).

    The output is a list of durations extracted from the input string.
    Durations are indicated by a number following the note (e.g. C4 or C4 2),
    or default to 1 if no explicit duration is given.

    Since the clarifying answer says the output should reflect durations rather than MIDI notes,
    this function extracts the durations from the input string, assuming default duration 1.

    Example:
    "C4 D#4 E4" => [1,1,1]
    "C4 2 D#4 3 E4" => [2,3,1]
    """

    # Pattern:
    # Note: [A-G][#b]?(\d*)  (octave optional)
    # Optional duration: a number following the note token (possibly separated by spaces)
    # We'll parse tokens in order and associate durations if they appear immediately after a note.

    tokens = music.strip().split()
    durations = []
    i = 0
    while i < len(tokens):
        token = tokens[i]

        # Check if token matches a note pattern: A-G with optional # or b and optional octave digits
        m = re.fullmatch(r"[A-Ga-g][#b]?(\d*)", token)
        if m:
            # Default duration
            duration = 1
            # Check if next token is a positive integer duration
            if i + 1 < len(tokens) and tokens[i+1].isdigit():
                duration = int(tokens[i+1])
                i += 1
            durations.append(duration)
        # If token doesn't match a note, just skip it (could be invalid input)
        i += 1

    return durations


