def circular_shift(x: int, y: int) -> str:
    digits = str(x)
    n = len(digits)
    if y > n:
        # If y is larger than number of digits, return the digits sorted ascending
        return ''.join(sorted(digits))
    y = y % n  # shift amount modulo length
    # Rotate digits to the left by y positions (standard shift)
    shifted = digits[y:] + digits[:y]
    return shifted


