import re

def anti_shuffle(data: str) -> str:
    # Split the input string into pieces and whitespace sequences
    parts = re.split(r'(\s+)', data)
    # For each piece that is not whitespace, sort its characters; else keep as is
    for i in range(0, len(parts), 2):
        parts[i] = ''.join(sorted(parts[i]))
    return ''.join(parts)


