def decode_shift(s: str):
    """
    returns decoded string by shifting every lowercase character by 5 backwards in the alphabet,
    leaving other characters unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted = chr((ord(ch) - ord('a') - 5) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(ch)
    return "".join(result)


