def anti_shuffle(s):
    def sort_word(word):
        return ''.join(sorted(word))

    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i].isspace():
            # accumulate and append spaces as is
            j = i
            while j < n and s[j].isspace():
                j += 1
            result.append(s[i:j])
            i = j
        else:
            # accumulate non-space word, sort it, append
            j = i
            while j < n and not s[j].isspace():
                j += 1
            word = s[i:j]
            result.append(sort_word(word))
            i = j
    return ''.join(result)


