def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Count the number of "drops" where arr[i] > arr[i+1]
    drops = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            drops += 1
            if drops > 1:
                return False
    # Also check the circular boundary arr[-1] > arr[0]
    if drops == 1 and arr[-1] > arr[0]:
        return False
    # If drops == 0, array is already sorted
    # If drops == 1 and arr[-1] <= arr[0], rotation is possible
    return True


