import string

def select_words(s, n):
    vowels = set("aeiouAEIOU")
    result = []
    for word in s.split():
        # Remove punctuation
        cleaned = word.translate(str.maketrans('', '', string.punctuation))
        if not cleaned:
            continue
        # Count consonants
        consonant_count = sum(1 for ch in cleaned if ch.isalpha() and ch not in vowels)
        if consonant_count == n:
            result.append(word)
    return result


