def anti_shuffle(s):
    import re
    def reorder_word(word):
        chars = list(word)
        sorted_chars = sorted(chars)
        if sorted_chars == chars:
            # Already ascending, so return descending
            return ''.join(sorted_chars[::-1])
        else:
            # Return ascending
            return ''.join(sorted_chars)

    # Split string into words and spaces using regex to keep spaces
    parts = re.split(r'(\s+)', s)
    result_parts = []
    for part in parts:
        if part.isspace() or part == '':
            # keep spaces as is
            result_parts.append(part)
        else:
            result_parts.append(reorder_word(part))
    return ''.join(result_parts)


