def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    # Check if arr is already sorted non-decreasing
    def is_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    # If already sorted non-decreasing, return True immediately
    if is_non_decreasing(arr):
        return True

    # Try all possible right shifts
    # One right shift: arr[-1], arr[0], arr[1], ..., arr[-2]
    # After k right shifts: arr[-k:], arr[:-k]
    for k in range(1, n):
        shifted = arr[-k:] + arr[:-k]
        if is_non_decreasing(shifted):
            return True
    return False


