def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of the maximum k unique numbers in arr.
    If k is 0, return an empty list.
    If there are fewer than k unique numbers, return all unique numbers sorted.
    """
    unique_nums = sorted(set(arr), reverse=True)
    return sorted(unique_nums[:k])


