def will_it_fly(q, w):
    if len(q) < 3:
        return False
    left_sum = sum(q[:len(q)//2])
    right_sum = sum(q[len(q)//2+1:])
    total_weight = sum(q)
    balanced = left_sum == right_sum
    return balanced and total_weight <= w


