def dif_Square(n: int) -> bool:
    # Every integer n can be expressed as difference of two squares iff n is not congruent to 2 mod 4.
    # Explanation:
    # a^2 - b^2 = (a-b)(a+b)
    # For integers a,b, all numbers congruent to 0,1,3 mod 4 can be represented, but not those equal to 2 mod 4.
    return n % 4 != 2


