def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle single digit numbers quickly
    if num < 9:
        return num + 1

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all digits are 9, the next palindrome is 10...01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to create a palindrome by mirroring the left half to the right
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    mid = length // 2

    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    pal = make_palindrome(left, odd)
    pal_num = int(pal)

    if pal_num > num:
        return pal_num

    # Increment the left part and re-mirror
    if odd:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        # If length changed due to carry (e.g. 999 -> 1000), adjust palindrome accordingly
        if len(left) > len(s[:mid+1]):
            # This means the palindrome length increases by 1, e.g. 999 -> 1001
            return int('1' + ('0' * (length - 1)) + '1')
        pal = make_palindrome(left, odd)
    else:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        if len(left) > len(s[:mid]):
            return int('1' + ('0' * (length - 1)) + '1')
        pal = make_palindrome(left, odd)

    return int(pal)


