def find_solution(a: int, b: int, n: int):
    # We want to find non-negative integers x, y such that a*x + b*y = n.
    # Return first found solution as ('x = ', x, ', y = ', y)
    # or 'No solution' if none exists.

    # Handle trivial cases
    if n < 0:
        return 'No solution'
    if a == 0 and b == 0:
        return ('x = ', 0, ', y = ', 0) if n == 0 else 'No solution'
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return ('x = ', 0, ', y = ', n // b)
        else:
            return 'No solution'
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return ('x = ', n // a, ', y = ', 0)
        else:
            return 'No solution'

    # We try x from 0 up to n//a (since x must be non-negative)
    max_x = n // a
    for x in range(max_x + 1):
        rem = n - a * x
        if rem < 0:
            break
        if rem % b == 0:
            y = rem // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
    return 'No solution'


