def decode_list(encoded):
    decoded = []
    i = 0
    n = len(encoded)
    while i < n:
        item = encoded[i]
        # If item is a pair (count, value)
        if (
            isinstance(item, (list, tuple))
            and len(item) == 2
            and isinstance(item[0], int)
        ):
            count, value = item
            decoded.extend([value] * count)
            i += 1
        # If item is an int and next item exists, treat as (count, value)
        elif isinstance(item, int) and i + 1 < n:
            count = item
            value = encoded[i + 1]
            decoded.extend([value] * count)
            i += 2
        else:
            # Single value without count: treat count as 1
            decoded.append(item)
            i += 1
    return decoded


