def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 0
    # dp[pos][val] = number of sequences of length pos ending with val
    dp = [ [0]*(m+1) for _ in range(n+1) ]
    # Base case: sequences of length 1
    for val in range(1, m+1):
        dp[1][val] = 1
    for pos in range(2, n+1):
        # For each val, sum dp[pos-1][prev] where val >= 2*prev
        # To optimize, we can precompute prefix sums of dp[pos-1]
        prefix = [0]*(m+1)
        for val in range(1, m+1):
            prefix[val] = prefix[val-1] + dp[pos-1][val]
        for val in range(1, m+1):
            max_prev = val // 2
            if max_prev >= 1:
                dp[pos][val] = prefix[max_prev]
            else:
                dp[pos][val] = 0
    return sum(dp[n][1:])


