def min_flip_to_make_string_alternate(s: str) -> int:
    # Pattern 1: starting with '0' -> expected chars alternate as 0,1,0,1,...
    flips_pattern1 = 0
    # Pattern 2: starting with '1' -> expected chars alternate as 1,0,1,0,...
    flips_pattern2 = 0

    for i, ch in enumerate(s):
        expected_char_p1 = '0' if i % 2 == 0 else '1'
        expected_char_p2 = '1' if i % 2 == 0 else '0'
        if ch != expected_char_p1:
            flips_pattern1 += 1
        if ch != expected_char_p2:
            flips_pattern2 += 1

    return min(flips_pattern1, flips_pattern2)


