from typing import List
from collections import Counter

def permute_string(s: str) -> List[str]:
    def backtrack(path, counter, length, result):
        if len(path) == length:
            result.append("".join(path))
            return
        for char in counter:
            if counter[char] > 0:
                path.append(char)
                counter[char] -= 1
                backtrack(path, counter, length, result)
                counter[char] += 1
                path.pop()

    result = []
    counter = Counter(s)
    backtrack([], counter, len(s), result)
    return result


