def find_Max(nums):
    left, right = 0, len(nums) - 1
    # If the array is not rotated (sorted ascending), the max is the last element
    if nums[left] < nums[right]:
        return nums[right]
    # Binary search for the max element in the rotated array
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # After the loop, left is the index of the smallest element,
    # so max is at left-1 (mod length)
    return nums[left - 1]


