def lucky_num(n):
    # Start with the list of odd numbers (classical lucky numbers are generated from odds)
    numbers = list(range(1, 2 * n * n, 2))  # Over-allocate to ensure enough lucky numbers
    idx = 1  # Start from second element (index 1), which is the first step for elimination

    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from index step-1
        # Note: indexing is zero-based, so step-1 is the first to remove
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            continue
        else:
            # Extend the list if needed (rarely happens)
            more = list(range(numbers[-1] + 2, numbers[-1] + 2 * n * n, 2))
            numbers.extend(more)

    return numbers[:n]


