def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        return 0
    # factorial(b) / factorial(a) = product of integers from a+1 to b
    # We want the last digit of this product

    product = 1
    for num in range(a + 1, b + 1):
        product = (product * (num % 10)) % 10
        # If product ends with 0, it will remain 0
        if product == 0:
            break
    return product


