def dif_Square(n: int) -> bool:
    # A number n can be represented as difference of two squares:
    # n = x^2 - y^2 = (x+y)(x-y)
    # Let a = x+y, b = x-y, then n = a*b
    # a and b are integers with the same parity (both odd or both even)
    # So n can be expressed as difference of two squares iff n is NOT congruent to 2 mod 4.
    return n % 4 != 2


