def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x):
        return x == x[::-1]

    # If all digits are 9, next palindrome is 10...01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Generate palindrome by mirroring the left half onto the right
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    left_half_len = (length + 1) // 2
    left_half = s[:left_half_len]

    # First candidate palindrome by mirroring left half
    candidate = make_palindrome(left_half, odd)
    if int(candidate) > n:
        return int(candidate)

    # If candidate <= n, increment the left half and mirror again
    # Increment left half as an integer
    left_num = int(left_half) + 1
    left_str = str(left_num)

    # If incrementing left half changes its length, the palindrome length increases by 1
    if len(left_str) > left_half_len:
        # For example: 99 -> after increment left half 100, palindrome length grows
        # Return palindrome of form 10...01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    return int(make_palindrome(left_str, odd))


