def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - (x // y) * t)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return 'No solution'
    k = n // g
    x = x0 * k
    y = y0 * k
    return ('x = ', x, ', y = ', y)


