from typing import List
from collections import Counter

def permute_string(s: str) -> List[str]:
    def backtrack(path, counter):
        if len(path) == len(s):
            result.append("".join(path))
            return
        for char in counter:
            if counter[char] > 0:
                path.append(char)
                counter[char] -= 1
                backtrack(path, counter)
                counter[char] += 1
                path.pop()

    result = []
    backtrack([], Counter(s))
    return result


