def find_Max(arr, low, high):
    # If the range is invalid or empty, return None
    if low > high:
        return None
    # If the range has only one element, return it
    if low == high:
        return arr[low]

    mid = (low + high) // 2

    # If mid element is greater than the next element,
    # mid element is the maximum
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]

    # If mid element is smaller than the previous element,
    # previous element is the maximum
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide which half to search
    if arr[low] >= arr[mid]:
        # Maximum is in left half
        return find_Max(arr, low, mid - 1)
    else:
        # Maximum is in right half
        return find_Max(arr, mid + 1, high)


