def lucky_num(n):
    # Start with the natural numbers list (odd numbers only)
    nums = list(range(1, 2 * n * 20, 2))  # Oversize to ensure enough lucky numbers
    idx = 1  # Start with the second number (index 1), which determines the step

    while idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th number starting from step-1 (0-based index)
        # We remove numbers at indices step-1, step-1 + step, step-1 + 2*step, ...
        del nums[step-1::step]
        idx += 1

    return nums[:n]


