def compute_Last_Digit(a, b):
    start, end = min(a, b) + 1, max(a, b)
    last_digit = 1
    for x in range(start, end + 1):
        last_digit = (last_digit * (x % 10)) % 10
        if last_digit == 0:
            break
    return last_digit


