def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Handle single-digit numbers quickly
    if n < 8:
        return n + 1 if n != 9 else 11
    if all(c == '9' for c in s):
        # Next palindrome after 999...9 is 100...001
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, length: int) -> int:
        if length % 2 == 0:
            pal_str = left + left[::-1]
        else:
            pal_str = left + left[-2::-1]
        return int(pal_str)

    half_len = (length + 1) // 2
    left = s[:half_len]
    pal = make_palindrome(left, length)

    if pal > n:
        return pal

    # Increment the left half and form palindrome again
    left_num = int(left) + 1
    left_str = str(left_num)
    # If incrementing left increases length (like 99->100), must handle differently
    if len(left_str) > len(left):
        # This means the palindrome length increases by 1, e.g. 999 -> 1001
        return int('1' + ('0' * (length - 1)) + '1')
    else:
        return make_palindrome(left_str, length)


