def find_solution(a: int, b: int, n: int):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None

    # We want to find non-negative integers x,y with a*x + b*y = n
    # and minimal x.

    # Iterate x from 0 to max possible:
    max_x = n // a
    for x in range(max_x + 1):
        rem = n - a * x
        if rem < 0:
            break
        if rem % b == 0:
            y = rem // b
            if y >= 0:
                return (x, y)
    return None


