def get_total_number_of_sequences(m: int, n: int) -> int:
    # dp[i][v]: number of sequences of length i ending with value v
    # Base case: sequences of length 1, each value from 1 to m is valid
    dp = [1] * (m + 1)  # dp for sequences of length 1, index 0 unused

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        for curr in range(1, m + 1):
            # sum over all prev where curr == 2*prev or prev == 2*curr
            # i.e. prev = curr//2 if curr even, and prev = curr*2 if <= m
            total = 0
            if curr % 2 == 0:
                prev = curr // 2
                total += dp[prev]
            prev = curr * 2
            if prev <= m:
                total += dp[prev]
            new_dp[curr] = total
        dp = new_dp

    return sum(dp[1:]) if n > 0 else 0


