def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            depth = dict_depth(v)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(v, (list, tuple)):
            for item in v:
                if isinstance(item, dict):
                    depth = dict_depth(item)
                    if depth > max_depth:
                        max_depth = depth
    return max_depth + 1


