def smallest_missing(arr, low, high):
    start = arr[low]
    end = arr[high]
    left, right = low, high

    while left <= right:
        mid = (left + right) // 2
        expected = start + (mid - low)
        if arr[mid] == expected:
            left = mid + 1
        else:
            right = mid - 1

    return start + (left - low)


