from typing import List

def permute_string(s: str) -> List[str]:
    def backtrack(path, used):
        if len(path) == len(chars):
            result.append(''.join(path))
            return
        for i in range(len(chars)):
            if used[i]:
                continue
            # Do NOT skip duplicates here, because duplicates should be included as separate permutations
            used[i] = True
            path.append(chars[i])
            backtrack(path, used)
            path.pop()
            used[i] = False

    chars = sorted(s)
    result = []
    used = [False] * len(chars)
    backtrack([], used)
    return result


