def add_string(lst, fmt):
    # Check that the format string contains exactly one substitution slot
    # We'll count the number of '{}' or '{something}' placeholders by attempting to format with two different values
    # If the number of replacement fields is not exactly one, raise an error.
    # However, since the format string can have named fields, use string.Formatter to count fields.
    from string import Formatter

    field_count = sum(1 for _, field_name, _, _ in Formatter().parse(fmt) if field_name is not None)
    if field_count != 1:
        raise ValueError("Format string must contain exactly one substitution slot")

    return [fmt.format(item) for item in lst]


