def find_Max(nums):
    if not nums:
        return None
    low, high = 0, len(nums) - 1
    # If array is not rotated
    if nums[low] < nums[high]:
        return nums[high]
    while low < high:
        mid = (low + high) // 2
        if nums[mid] > nums[high]:
            low = mid + 1
        else:
            high = mid
    # low is now index of minimum element, max is element before it (circular)
    return nums[low - 1 if low > 0 else len(nums) - 1]


