def lucky_num(n):
    numbers = list(range(1, 2 * n * 10, 2))  # start with odd numbers, oversize range to ensure enough lucky numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            # We can stop early only if we have at least n lucky numbers
            continue
    return numbers[:n]


