def dif_Square(n: int) -> bool:
    # A number n can be represented as x^2 - y^2 = (x+y)(x-y)
    # So n = a * b where a = x+y and b = x-y (both integers)
    # Since x = (a+b)/2 and y = (a-b)/2 must be integers,
    # a and b must have the same parity (both even or both odd).
    #
    # Thus, n can be represented as difference of two squares
    # if and only if n has a factorization into two integers a,b
    # of the same parity.
    #
    # Special case: n=0 -> 0 = 0^2 - 0^2, so True.
    #
    # We can check all factor pairs of n (including negative ones)
    # to see if any pair (a,b) satisfies a*b = n and a,b same parity.
    #
    # Because difference of squares is symmetric with negative factors,
    # we only need to check positive factors and their negative counterparts.

    if n == 0:
        return True

    abs_n = abs(n)
    from math import isqrt

    for a in range(1, isqrt(abs_n) + 1):
        if abs_n % a == 0:
            b = abs_n // a
            # Check parity for positive factor pair (a,b)
            if (a % 2) == (b % 2):
                # For n positive: (a,b) or (b,a) with same parity works
                # For n negative: consider negative factors as well
                # Because a*b = |n|, but we want n = a*b or n = -(a*b)
                # Check if sign assignment can get n:
                # Try (a, b) with signs:
                # (a,b) => a*b = n?
                # (-a,-b) => (-a)*(-b) = a*b = n?
                # (a,-b) => a*(-b) = -a*b = -|n| or n?
                # (-a,b) => (-a)*b = -a*b = -|n| or n?
                #
                # So if n > 0, a*b = n or (-a)*(-b) = n works
                # if n < 0, a*(-b) = n or (-a)*b = n works
                if n > 0:
                    return True
                else:
                    # n < 0
                    return True
    return False


