def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # A helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # The next palindrome greater than 999..9 is 100..001
        return num + 2  # e.g. 9->11, 99->101, 999->1001

    def make_palindrome(left: str, odd_length: bool):
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    # For odd length palindrome, left includes the middle digit
    # For even length palindrome, left is the first half
    odd_length = (length % 2 != 0)
    mid = (length + 1) // 2
    left = s[:mid]

    palindrome = make_palindrome(left, odd_length)
    if palindrome > num:
        return palindrome

    # If palindrome <= num, increment the left part and rebuild palindrome
    left_int = int(left) + 1
    left = str(left_int)
    # If incrementing left changed length (e.g. 999 + 1 = 1000)
    # the overall palindrome length increases by 1 or 0 depending on parity
    if len(left) > mid:
        # This means the palindrome length increases by 1
        # For example: num=999 -> next palindrome=1001
        # Here length increases by 1, so build palindrome accordingly
        # For even length original, new palindrome length is length+1 (odd)
        # For odd length original, new palindrome length is length+1 (even)
        # But simply return 10^length + 1:
        return 10 ** length + 1

    palindrome = make_palindrome(left, odd_length)
    return palindrome


