def find_solution(a, b, n):
    from math import gcd

    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        d, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return d, x, y

    d = gcd(a, b)
    if n % d != 0:
        return 'No solution'

    d, x0, y0 = extended_gcd(a, b)
    x0 *= n // d
    y0 *= n // d

    # General solution: x = x0 + k*(b/d), y = y0 - k*(a/d)
    # We want the smallest non-negative x, so find k s.t. x>=0 and minimal.
    # Solve for k: x0 + k*(b/d) >= 0  => k >= -x0 / (b/d)

    b_div = b // d
    a_div = a // d

    # If b_div == 0, then a*x = n, so x = n/a if integer, y arbitrary
    # But since gcd divides n, a_div != 0
    if b_div == 0:
        if x0 >= 0:
            return (x0, y0)
        else:
            return 'No solution'

    # Calculate k to make x minimal non-negative
    k = (-x0 + b_div - 1) // b_div  # ceil division for k >= -x0/(b/d)

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0:
        return 'No solution'
    return (x, y)


