def min_flip_to_make_string_alternate(s: str) -> int:
    def flips_needed(start_char: str) -> int:
        flips = 0
        expected = start_char
        for ch in s:
            if ch != expected:
                flips += 1
            expected = '1' if expected == '0' else '0'
        return flips

    return min(flips_needed('0'), flips_needed('1'))


