def smallest_missing(arr):
    # Since the array is sorted, we can use binary search to find the smallest missing non-negative integer starting from 0.
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        # We want to find the smallest index where arr[index] != index
        # But arr may start with values > 0, so we compare arr[mid] with mid
        # If arr[mid] > mid, missing number is at or before mid
        # If arr[mid] == mid, missing number is after mid
        if arr[mid] > mid:
            right = mid
        else:
            left = mid + 1
    return left


