def find_Max(arr):
    if not arr:
        return None  # or raise an error if empty input is invalid

    low, high = 0, len(arr) - 1

    # If the array is not rotated (sorted ascending), last element is max
    if arr[low] < arr[high]:
        return arr[high]

    while low <= high:
        mid = (low + high) // 2

        # Check if mid element is max by comparing with neighbors
        if mid < len(arr) - 1 and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > 0 and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which half to go
        if arr[mid] >= arr[low]:
            # max is in right half
            low = mid + 1
        else:
            high = mid - 1

    # Fallback, should not reach here for a valid rotated sorted array
    return arr[0]


