def filter_data(students, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters students by their height and width attributes.

    Parameters:
    - students: dict mapping student identifiers to dicts with at least 'height' and 'width' keys.
    - min_height: minimum height to include (inclusive). If None, no minimum.
    - max_height: maximum height to include (inclusive). If None, no maximum.
    - min_width: minimum width to include (inclusive). If None, no minimum.
    - max_width: maximum width to include (inclusive). If None, no maximum.

    Returns:
    - dict of students filtered by the given height and width bounds.
    """
    def in_range(value, min_val, max_val):
        if (min_val is not None) and (value < min_val):
            return False
        if (max_val is not None) and (value > max_val):
            return False
        return True

    filtered = {}
    for key, attrs in students.items():
        height = attrs.get('height')
        width = attrs.get('width')
        if height is None or width is None:
            continue
        if in_range(height, min_height, max_height) and in_range(width, min_width, max_width):
            filtered[key] = attrs
    return filtered


