def lucky_num(n):
    # Start with a list of odd numbers; lucky numbers start like this
    numbers = list(range(1, 2 * n * 10, 2))
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from index step-1
        del numbers[step - 1::step]
        idx += 1
        # If list too short, extend it
        if len(numbers) < n:
            last = numbers[-1]
            # Extend by odd numbers continuing after last
            numbers.extend(range(last + 2, last + 2 + (n * 10), 2))
    return numbers[:n]


