def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of two squares if and only if
    # n is not congruent to 2 mod 4.
    # Reason:
    # Difference of squares: a^2 - b^2 = (a+b)(a-b)
    # Both (a+b) and (a-b) have the same parity, so their product is congruent to 0 or 1 mod 4,
    # thus difference of squares can be congruent to 0,1 or 3 mod 4, but never 2 mod 4.
    return n % 4 != 2


