def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)  # start from next integer strictly greater than n
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If all 9's, e.g. 9, 99, 999 -> next palindrome is 11, 101, 1001 ...
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    while True:
        if is_palindrome(s):
            return int(s)
        # Generate the next palindrome candidate by mirroring left to right
        half = length // 2
        if length % 2 == 0:
            left = s[:half]
            middle = ''
            right = s[half:]
        else:
            left = s[:half]
            middle = s[half]
            right = s[half+1:]

        # Construct palindrome by mirroring left + middle + reversed left
        if middle:
            pal = left + middle + left[::-1]
        else:
            pal = left + left[::-1]

        if pal > s:
            s = pal
        else:
            # Increment the middle part and propagate carry if needed
            if middle:
                # Increment middle digit
                increment_part = left + middle
            else:
                increment_part = left

            increment_num = int(increment_part) + 1
            increment_str = str(increment_num)

            # If length changed after increment (e.g. 999 + 1 = 1000)
            if len(increment_str) > len(increment_part):
                # When length grows, palindrome length may grow
                s = '1' + ('0' * (length - 1)) + '1'
                length = len(s)
            else:
                if middle:
                    left = increment_str[:-1]
                    middle = increment_str[-1]
                    s = left + middle + left[::-1]
                else:
                    left = increment_str
                    s = left + left[::-1]


