from functools import lru_cache

def get_total_number_of_sequences(n, k):
    @lru_cache(None)
    def count(pos, prev):
        if pos == n:
            return 1
        total = 0
        start = max(prev, 1) if prev != 0 else 1
        for val in range(start, k + 1):
            if prev == 0 or val >= 2 * prev:
                total += count(pos + 1, val)
        return total

    return count(0, 0)


