def remove_column(data, key_or_index):
    if isinstance(data, dict):
        return {k: remove_column(v, key_or_index) for k, v in data.items() if k != key_or_index}
    elif isinstance(data, list):
        # Remove element at index key_or_index if it's a valid index
        # Then recursively process remaining elements
        if isinstance(key_or_index, int) and 0 <= key_or_index < len(data):
            new_list = data[:key_or_index] + data[key_or_index+1:]
        else:
            new_list = data[:]
        return [remove_column(elem, key_or_index) for elem in new_list]
    else:
        return data


