def min_flip_to_make_string_alternate(s: str) -> int:
    # Count flips needed if string starts with '0'
    flips_start_with_0 = sum((c != str(i % 2)) for i, c in enumerate(s))
    # Count flips needed if string starts with '1'
    flips_start_with_1 = sum((c != str((i + 1) % 2)) for i, c in enumerate(s))
    return min(flips_start_with_0, flips_start_with_1)


