import re

def capital_words_spaces(s: str) -> str:
    # Pattern explanation:
    # (?<!^): negative lookbehind to ensure we don't match at the start of the string
    # (?=[A-Z][a-z]): positive lookahead for uppercase letter followed by lowercase letter
    # This matches positions before uppercase letters that start a new word (except start of string)
    return re.sub(r'(?<!^)(?=[A-Z][a-z])', ' ', s)


