def lucky_num(n):
    # Initialize the list with odd numbers starting from 1
    # We start with a sufficiently large list to ensure we can get n lucky numbers after sieving
    # The length is arbitrary but should be large enough; if not, we could increase it dynamically
    # For typical small n, 2*n*10 is enough
    length = n * 20
    numbers = list(range(1, length * 2, 2))  # odd numbers starting from 1

    idx = 1  # Start from the second number in the list (index 1)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list, starting from index step-1
        # Because indexing is 0-based, and counting starts at 1 in the sieve definition
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            continue
        # If the list becomes too small before we get n lucky numbers, extend it
        if idx >= len(numbers):
            # Extend numbers with next odd numbers beyond current max
            last = numbers[-1]
            extra = list(range(last + 2, last + 2 + (length * 2), 2))
            numbers.extend(extra)

    return numbers[:n]


