def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x*y with x,y integers.
    # Also, a = (x+y)/2, b = (y-x)/2 must be integers, so x and y have the same parity.
    # So n can be expressed as difference of squares iff n has a factorization n = x*y
    # where x and y have the same parity.
    # For n=0, 0=0^2 - 0^2 is True.
    if n == 0:
        return True
    abs_n = abs(n)
    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check if x,y have same parity
            if (x % 2) == (y % 2):
                return True
    return False


