def find_solution(a, b, n):
    if b == 0:
        # Then a*x = n, so check if n is divisible by a
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return []
    if a == 0:
        # Then b*y = n, so check if n divisible by b
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return []

    for x in range(0, n + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    return []


