def get_total_number_of_sequences(N: int, K: int) -> int:
    # Counts sequences of length K with elements ≤ N,
    # where each next element is at least twice the previous.
    # Elements are positive integers.

    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(prev: int, length: int) -> int:
        if length == K:
            return 1
        total = 0
        start = max(1, prev * 2)
        for next_elem in range(start, N + 1):
            total += count_sequences(next_elem, length + 1)
        return total

    total_count = 0
    for first_elem in range(1, N + 1):
        total_count += count_sequences(first_elem, 1)
    return total_count


