from collections.abc import Iterable

def remove_column(data, pos):
    if not isinstance(data, Iterable) or isinstance(data, (str, bytes)):
        return data
    # For iterables, produce the same type but with element at pos removed from each inner grouping
    # For sequences (list, tuple), preserve type and order
    # For other iterables (e.g. sets, dicts?), treat accordingly:
    #   - dict is iterable over keys; unclear if inner grouping is dict keys or dict items;
    #     safest is to treat dict as leaf (not a grouping), so leave unchanged.
    # We'll treat only list, tuple as groupings to remove from; others return as is.

    # Decide if current data is a grouping to remove from:
    if isinstance(data, (list, tuple)):
        # Process each element recursively
        inner = [remove_column(elem, pos) for elem in data]
        # For each inner element, if it's a grouping, remove element at pos
        # Actually, the spec says remove element at pos from each inner grouping at every level.
        # So "each inner grouping" means: in the current iterable, remove the element at pos

        # So at current level, remove element at pos (if exists)
        if pos < len(inner):
            del inner[pos]

        # Return same type as original
        return type(data)(inner)

    # For other iterables (including sets), just recurse on elements but do not remove element at pos
    # because they are not indexable groupings
    return data


