import re

def move_num(text: str, numbers: list[int]) -> str:
    # Find all numeric substrings in text
    nums_in_text = re.findall(r'\d+', text)
    # Iterator over numbers to insert
    nums_iter = iter(numbers)

    def replace_num(match):
        # Replace each found numeric substring with next number from numbers, if any
        try:
            return str(next(nums_iter))
        except StopIteration:
            # If no more numbers to insert, keep original numeric substring
            return match.group(0)

    replaced_text = re.sub(r'\d+', replace_num, text)

    # Append any remaining numbers (not used for replacement) separated by spaces
    remaining = list(nums_iter)
    if remaining:
        if replaced_text and not replaced_text.endswith(' '):
            replaced_text += ' '
        replaced_text += ' '.join(str(n) for n in remaining)

    return replaced_text


