def str_to_tuple(s: str, from_group_sep: str = ",", from_inner_sep: str = "-", to_group_sep: str = ";", to_inner_sep: str = ":") -> str:
    groups = s.split(from_group_sep)
    converted_groups = []
    for group in groups:
        parts = group.split(from_inner_sep)
        converted_groups.append(to_inner_sep.join(parts))
    return to_group_sep.join(converted_groups)


