def lucky_num(n):
    numbers = list(range(1, 2 * n * 10))  # a large enough range to find n lucky numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # remove every step-th number starting from index step-1
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n:
            continue
        else:
            # extend the list if needed (unlikely)
            numbers.extend(range(numbers[-1]+1, numbers[-1]+1+10*n))
    return numbers[:n]


