def compute_Last_Digit(a: int, b: int) -> int:
    # We want the last digit of factorial(b) / factorial(a) = product of (a+1)*(a+2)*...*b

    # If b == a, the result is 1, last digit 1
    if b == a:
        return 1

    # If b < a, factorial(b)//factorial(a) is not defined as integer division (b! < a!)
    # Problem states b >= a, so no need to handle this case

    # The product is from (a+1) to b
    # We want the last digit of that product.
    # The product may be large, but we only need last digit, so we can multiply modulo 10.

    last_digit = 1
    for num in range(a+1, b+1):
        last_digit = (last_digit * (num % 10)) % 10

    return last_digit


