def next_smallest_palindrome(num: int) -> int | None:
    if num <= 1:
        return None  # no palindrome smaller than 0 or 1

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # Start from num-1 and go down until we find a palindrome
    for candidate in range(num - 1, -1, -1):
        if is_palindrome(candidate):
            return candidate
    return None


