def find_solution(a: int, b: int, n: int):
    # Extended Euclidean Algorithm to find gcd and one solution to ax + by = gcd(a,b)
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        return gcd, y1, x1 - (x // y) * y1

    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return None

    # scale the solution to ax + by = n
    x0 *= n // gcd
    y0 *= n // gcd

    # a and b divided by gcd
    a_div = a // gcd
    b_div = b // gcd

    # We want nonnegative solutions x, y >= 0
    # General solutions: x = x0 + k * (b/gcd), y = y0 - k * (a/gcd)
    # Find k so that both x and y are >=0

    # Solve inequalities:
    # x0 + k * b_div >= 0  => k >= -x0 / b_div
    # y0 - k * a_div >= 0  => k <= y0 / a_div

    # Since a_div and b_div are positive (gcd divides both a and b),
    # compute the range of valid k values
    import math

    k_min = math.ceil(-x0 / b_div) if b_div != 0 else float('-inf')
    k_max = math.floor(y0 / a_div) if a_div != 0 else float('inf')

    if k_min > k_max:
        return None

    # Among these k, find any integer k in [k_min, k_max]
    # Choose the k that yields smallest nonnegative x (or any valid k)
    k = k_min
    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0 or y < 0:
        return None

    return (x, y)


