def decode_list(rle_list):
    """
    Decode a run-length encoded list where the input is a list of pairs [count, value].
    Each pair indicates how many times the value should be repeated in the output list.

    For example:
    decode_list([[3,5],[2,7]]) -> [5,5,5,7,7]
    """
    decoded = []
    for count, value in rle_list:
        decoded.extend([value] * count)
    return decoded


