def lucky_num(n):
    nums = list(range(1, 2*n*10, 2))  # start with odd numbers, large enough range
    idx = 1
    while idx < len(nums) and len(nums) > n:
        step = nums[idx]
        if step > len(nums):
            break
        # remove every step-th number (1-based indexing)
        nums = [num for i, num in enumerate(nums, 1) if i % step != 0]
        idx += 1
    return nums[:n]


