def tuple_to_set(*tuples):
    result = set()
    for t in tuples:
        result.update(t)
    return result

def get_noOfways(n, m):
    if m != 2:
        return 0
    # Number of ways to tile 2 x n board with 2 x 1 tiles is Fibonacci-like:
    # ways(0) = 1 (empty board)
    # ways(1) = 1
    # ways(n) = ways(n-1) + ways(n-2)
    if n < 0:
        return 0
    if n == 0 or n == 1:
        return 1
    a, b = 1, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b


